var e={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Vind de hoogste volumetrische flow (mm³/s) die je hotend kan volhouden - door de flow op te voeren terwijl je de StallGuard-belasting van de extruder in de gaten houdt voor het moment dat het tandwiel slipt. Bekijk eerst het plan; de live test verwarmt en extrudeert, dus maak de printer klaar voordat je hem draait.`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Help`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Over Max-Flow`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Sluiten`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Hoe te gebruiken`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Stel de testtemperatuur en je filamentdiameter in (kies een hotend om voor te vullen).`}},{t:0,b:{t:2,i:[{t:3}],s:`Bekijk het plan - het toont elke flowstap en hoeveel filament er wordt doorgevoerd.`}},{t:0,b:{t:2,i:[{t:3}],s:`Vink de veiligheidschecklist aan en draai dan de live test (verwarmt + extrudeert).`}},{t:0,b:{t:2,i:[{t:3}],s:`Lees de maximaal volgehouden flow af en kopieer de voorgestelde slicerwaarde.`}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Hoe de test werkt`}},body:{t:0,b:{t:2,i:[{t:3}],s:`De extruder voert filament door bij een gestaag oplopende volumetrische flow. Zolang het getande wiel netjes grijpt blijft de StallGuard-belastingswaarde strak; zodra het begint te slippen springen de waarden alle kanten op. De hoogste flow die wordt bereikt vóór die sprong is je houdbare maximale flow. De ramp stopt zodra slip wordt gedetecteerd, dus er wordt geen filament voorbij de eerste slip vermalen.`}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard-slipdetectie`}},body:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard is een functie van de TMC-driver die de motorbelasting rapporteert. Deze test bemonstert die vele keren per flowstap en zoekt naar een plotselinge toename in spreiding (IQR) of variatie (CV) - het kenmerk van het tandwiel dat zijn grip verliest. De drempels komen uit een profiel per driver. Let op: op een TMC2209-extruder gebruikt dit het experimentele SG4-pad, dus behandel de eerste run als een kalibratie.`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Veiligheid`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Dit is een hete, bewegende test die de extruder bewust laat slippen. Laad filament, zorg dat de nozzle vrij is (boven het bed of een afvalplek) en blijf in de buurt. De run wordt geweigerd terwijl de printer print, en de verwarming wordt altijd uitgeschakeld als hij klaar is.`}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:`Het resultaat gebruiken`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Zet de voorgestelde waarde in de "max volumetric speed" van je slicer (per filament). Het conservatieve cijfer (80% van het gemeten maximum) is een veilige limiet voor dagelijks gebruik; het gebalanceerde cijfer (90%) duwt iets harder. Hogere hotendtemperaturen verhogen doorgaans de haalbare flow.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Woordenlijst`}},body:{t:0,b:{static:``,t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:`Volumetrische flow`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Hoeveel plastic de hotend per seconde smelt (mm³/s) - de echte snelheidslimiet voor snel printen.`}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een signaal van de TMC-driver dat de mechanische motorbelasting rapporteert, hier gebruikt om slip van de extruder te detecteren.`}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:`Slip`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Wanneer het extrudertandwiel het filament niet snel genoeg meer kan grijpen en overslaat - het flowplafond.`}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:`Smeltzone`}},def:{t:0,b:{t:2,i:[{t:3}],s:`De verwarmde lengte van de hotend; een langere smeltzone (bijv. Volcano) houdt een hogere flow vol.`}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:`Testparameters`}},temperature:{t:0,b:{t:2,i:[{t:3}],s:`Temperatuur (°C)`}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:`Filament Ø (mm)`}},hotend:{t:0,b:{t:2,i:[{t:3}],s:`Hotend (optioneel)`}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:`- geen -`}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:`Verwacht ~`},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:`Startflow (mm³/s)`}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:`Eindflow (mm³/s)`}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:`Stap (mm³/s)`}},samples:{t:0,b:{t:2,i:[{t:3}],s:`Samples / stap`}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:`Extruderen / stap (mm)`}},driver:{t:0,b:{t:2,i:[{t:3}],s:`Extruderdriver`}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:`gedetecteerd vanaf de printer`}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:`StealthChop automatisch inschakelen voor de test`}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:`Alleen TMC2209/2240: schrijft tijdelijk een stealthchop_threshold naar de extruder zodat StallGuard kan lezen, en zet het na de test weer als commentaar. Herstelt printer.cfg; firmware-herstart in beide richtingen.`}},method:{t:0,b:{t:2,i:[{t:3}],s:`Detectiemethode`}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:`Auto gebruikt StallGuard en valt terug op de accelerometer in de toolhead (trilling) wanneer StallGuard niet kan lezen. De accelerometermethode is experimenteel.`}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:`Auto`}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:`StallGuard`}},accel:{t:0,b:{t:2,i:[{t:3}],s:`Versnellingsmeter`}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:`Plan bekijken`}},title:{t:0,b:{t:2,i:[{t:3}],s:`Geplande ramp`}},stepCount:{t:0,b:{t:2,i:[{t:4,k:`count`},{t:3,v:` stappen`}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:`mm`},{t:3,v:` mm filament`}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:`StallGuard-veld: `},{t:4,k:`field`}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:`Geen StallGuard-veld bekend voor deze driver`}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:`Flow (mm³/s)`}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:`Voedingssnelheid (mm/min)`}},warning:{t:0,b:{t:2,i:[{t:3}],s:`De live test verwarmt de hotend en extrudeert filament, bewust tot het punt van slip. Alleen voorbeeld - er draait nog niets.`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Voordat je draait - veiligheidschecklist`}},items:[{t:0,b:{t:2,i:[{t:3}],s:`Filament is geladen en voert vrij door.`}},{t:0,b:{t:2,i:[{t:3}],s:`De nozzle is vrij - boven het bed of een afvalbak, niet in de lucht op onderdelen.`}},{t:0,b:{t:2,i:[{t:3}],s:`Ik accepteer dat dit bewust wat filament zal vermalen/laten slippen.`}},{t:0,b:{t:2,i:[{t:3}],s:`Ik blijf de hele test bij de printer.`}}],ack:{t:0,b:{t:2,i:[{t:3}],s:`Ik heb al het bovenstaande gedaan en de printer is klaar`}},note:{t:0,b:{t:2,i:[{t:3}],s:`De run wordt geweigerd tijdens het printen; de verwarming wordt aan het einde automatisch uitgeschakeld.`}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:`Live test draaien`}},running:{t:0,b:{t:2,i:[{t:3}],s:`Bezig… (verwarmen + extruderen)`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`De live max-flow test starten?`}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:`Dit verwarmt de hotend tot `},{t:4,k:`temp`},{t:3,v:` °C en extrudeert tot `},{t:4,k:`mm`},{t:3,v:` mm filament, met een ramp totdat de extruder slipt.`}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Nu draaien`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annuleren`}},busy:{t:0,b:{t:2,i:[{t:3}],s:`Geweigerd: de printer is bezig (printen of gepauzeerd). Probeer het opnieuw wanneer hij inactief is.`}},error:{t:0,b:{t:2,i:[{t:3}],s:`De test is mislukt.`}},noSg:{t:0,b:{t:2,i:[{t:3}],s:`Er zijn geen StallGuard-samples gelezen - het slipresultaat is mogelijk onbetrouwbaar. Het live SG-veld van de driver moet waarschijnlijk worden aangepast voor dit model.`}},progress:{t:0,b:{t:2,i:[{t:3,v:`Stap `},{t:4,k:`step`},{t:3,v:`/`},{t:4,k:`total`},{t:3,v:` - `},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:`Verwarmen / starten…`}},abort:{t:0,b:{t:2,i:[{t:3}],s:`Run afbreken`}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:`Afbreken…`}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:`Run afgebroken - de verwarming is uitgeschakeld.`}},reattached:{t:0,b:{t:2,i:[{t:3}],s:`Opnieuw gekoppeld: dit resultaat is voltooid terwijl de pagina weg was.`}},failed:{t:0,b:{t:2,i:[{t:3}],s:`Max-flow run mislukt.`}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:`Bij afbreken wordt de verwarming altijd uitgeschakeld.`}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:`Voor het verwarmen homed de printer (indien nodig) en centreert de nozzle voor een vrij zicht.`}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:`StealthChop inschakelen…`}},homing:{t:0,b:{t:2,i:[{t:3}],s:`De printer homen…`}},centering:{t:0,b:{t:2,i:[{t:3}],s:`De nozzle centreren…`}},heating:{t:0,b:{t:2,i:[{t:3}],s:`De hotend verwarmen…`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Het StallGuard-signaal controleren…`}},ramp:{t:0,b:{t:2,i:[{t:3}],s:`De flow opvoeren…`}},reverting:{t:0,b:{t:2,i:[{t:3}],s:`De config herstellen…`}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:`Home`}},center:{t:0,b:{t:2,i:[{t:3}],s:`Centreren`}},heat:{t:0,b:{t:2,i:[{t:3}],s:`Verwarmen`}},check:{t:0,b:{t:2,i:[{t:3}],s:`Controleren`}},ramp:{t:0,b:{t:2,i:[{t:3}],s:`Ramp`}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:`Live camera`}},live:{t:0,b:{t:2,i:[{t:3}],s:`LIVE`}},error:{t:0,b:{t:2,i:[{t:3}],s:`Camera niet beschikbaar.`}},willShow:{t:0,b:{t:2,i:[{t:3}],s:`Een live camerabeeld toont de nozzle tijdens de test.`}},minimize:{t:0,b:{t:2,i:[{t:3}],s:`Minimaliseren`}},maximize:{t:0,b:{t:2,i:[{t:3}],s:`Maximaliseren`}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:`Vergroten`}},shrink:{t:0,b:{t:2,i:[{t:3}],s:`Verkleinen`}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:`Resultaat`}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:`Max volgehouden flow`}},slipAt:{t:0,b:{t:2,i:[{t:3,v:`Slip gedetecteerd bij `},{t:4,k:`flow`},{t:3,v:` mm³/s`}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:`Geen slip tot de hoogst geteste flow`}},reason:{t:0,b:{t:2,i:[{t:3}],s:`Detail`}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:`Voorgestelde slicerwaarden (max volumetric speed)`}},conservative:{t:0,b:{t:2,i:[{t:3}],s:`Conservatief (80%)`}},balanced:{t:0,b:{t:2,i:[{t:3}],s:`Gebalanceerd (90%)`}},units:{t:0,b:{t:2,i:[{t:3}],s:`mm³/s`}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:`Eerder gemeten (`},{t:4,k:`at`},{t:3,v:`) - draai opnieuw voor verse cijfers.`}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:`Onbetrouwbaar - geen StallGuard-signaal`}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:`bereikt, niet bevestigd`}},via:{t:0,b:{t:2,i:[{t:3,v:`Gemeten via `},{t:4,k:`method`}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:`Gemeten via trilling (accelerometer) - experimenteel; behandel het getal als richtlijn, niet als exact plafond.`}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:`Hotends laden…`}}}}};export{e as default};